function header(title,sub){const o=op();return `<div id="opening69" data-ui="UI-OPENING-69"><div class="op69-heading"><div><span class="op69-eyebrow">စတင်လက်ကျန် · ${o.status==='approved'?'အတည်ပြုပြီး':'မူကြမ်း'}</span><h1>${esc(title)}</h1><p class="subtitle">${esc(sub)}</p></div><span class="pill ${o.status==='approved'?'':'blue'}">${o.status==='approved'?'ပိုင်ရှင် အတည်ပြုပြီး':'မူကြမ်း'}</span></div><div id="opening69Error" class="form-error" role="alert"></div>`;}
function footer(){return `<div class="op69-bottom"><span id="opening69Saved" role="status">${editable()?'ဖြည့်ထားသည်များကို မူကြမ်းအဖြစ် သိမ်းထားပါသည်။':'အတည်ပြုစာရင်းကို ကြည့်နေပါသည်။'}</span>${editable()?button('မူကြမ်း သိမ်းမယ်','opening69SaveDraft()','secondary','check'):''}${ui.view!=='review'?button('အားလုံး ပြန်စစ်မယ်',"opening69View('review')",'primary','eye'):''}</div></div>`;}
function datePanel(){const o=op();return `<section class="card op69-date"><div>${field('Software စသုံးမည့်ရက်','op69Start',{type:'date',value:o.startDate,required:true,extra:readonly()+' data-op69="start"'})}<p class="field-help">${dateOK(o.startDate)?shortDate(prevDate(o.startDate)):'—'} အဆုံးရှိ လက်ကျန်များကို ထည့်ပါ။ နေ့တိုင်းစစ်သော နေ့ဖွင့်ငွေနှင့် သီးခြားဖြစ်သည်။</p></div><div class="op69-date-help">အောက်ပါ သုံးပိုင်းကို ဖြည့်ပြီး ပိုင်ရှင်က ပြန်စစ်အတည်ပြုပါမယ်။</div></section>`;}
function groupStatus(kind){const o=op();return kind==='owned'?o.own.checked&&state.masters.accounts.every(a=>o.accounts[a.id]?.checked):o.groups[kind];}
function home(){const o=op();return header('စတင်လက်ကျန် ထည့်မယ်','သိပြီးသား ကုန်နဲ့ငွေကို အဆင့်လိုက် ဖြည့်ပါ။')+back('သတ်မှတ်ချက်များသို့',"beginSetup()")+datePanel()+(o.pendingStock?`<section class="op69-home-banner"><div><strong>မသိမ်းရသေးသော ကုန်လိုင်းမူကြမ်း ရှိပါသည်။</strong><p>နောက်ဆုံးဖြည့်ထားသည့် ကုန်လိုင်းကို ဆက်ဖြည့်နိုင်ပါသည်။</p></div><div class="row wrap">${button('ဆက်ဖြည့်မယ်','opening69ResumeStock()','primary')}${button('ဤကုန်လိုင်းမူကြမ်း ဖယ်မယ်','opening69DiscardStock()','secondary')}</div></section>`:'')+`<div class="op69-choices">${[['owned','stock','ကိုယ့်ပွဲရုံမှာ ရှိပြီးသား ကုန်နဲ့ငွေ'],['supplier','users','ကုန်သည်ပိုင်ကုန်၊ ပေးရန်နဲ့ ကြိုငွေ'],['buyer','sale','မထုတ်ရသေးတဲ့ကုန်၊ ရရန်နဲ့ ကြိုပေးငွေ']].map(([k,i,t],idx)=>`<button type="button" class="card op69-choice" onclick="opening69Scope('${k}')"><span class="op69-step">${idx+1}</span><span class="icon-box">${I(i)}</span><strong>${labels[k]}</strong><span>${t}</span><small>${groupStatus(k)?'စစ်ပြီးပါပြီ':'ဖြည့်ရန် / ပြန်စစ်ရန်'} ${I('arrow')}</small></button>`).join('')}</div><section class="op69-guide"><strong>အသုံးပြုပုံ</strong><p>ပွဲရုံပိုင် → ကုန်သည် → ဝယ်သူ → အားလုံး ပြန်စစ်မယ်။ အမည်အသစ်လိုရင် သက်ဆိုင်ရာနေရာမှာ ထည့်နိုင်ပါတယ်။</p><p>ရှိပြီးသားစာရင်းကို သီးခြားပြထားပါသည်။ စာရင်းမသွင်းရသေးသော လက်ကျန်များကိုသာ ထပ်ဖြည့်ပါ။</p></section>`+footer();}
function question(key,text,answer,fn){return `<div class="op69-question"><strong>${esc(text)}</strong><div class="op69-answers" role="group" aria-label="${esc(text)}"><button type="button" class="btn ${answer==='yes'?'btn-primary':'btn-secondary'}" aria-pressed="${answer==='yes'}" onclick="${fn}('yes')" ${readonly()}>ရှိသည်</button><button type="button" class="btn ${answer==='no'?'btn-primary':'btn-secondary'}" aria-pressed="${answer==='no'}" onclick="${fn}('no')" ${readonly()}>မရှိပါ</button></div>${answer===null||answer===undefined?'<small class="field-help">မဖြေရသေးပါ</small>':''}</div>`;}
function existingLots(kind,id){return state.lots.filter(l=>l.qty>0&&(kind==='owned'?l.owner==='owned':kind==='supplier'?l.owner==='supplier'&&(l.partnerId===id||state.receipts.some(r=>r.id===l.receiptId&&r.partnerId===id)):l.owner==='customer'&&(l.buyerId===id||state.sales.some(s=>s.id===l.saleId&&s.buyerId===id))));}
function existingStock(kind,id){const lots=existingLots(kind,id);if(!lots.length)return '';return `<details class="op69-existing"><summary>ရှိပြီးသား ကုန်လက်ကျန် · ${vissText37(sum(lots,l=>l.qty))} ပိဿာ</summary><p class="field-help">အောက်ပါကုန်များမှာ စာရင်းထဲ ရှိပြီးသားဖြစ်သည်။ ထပ်ဖြည့်ရန် မလိုပါ။</p>${lots.map(l=>`<div class="op69-line"><span>${esc(l.product)} · ${esc(l.grade)} · ${esc(W(l.warehouse))}</span><strong>${vissText37(l.qty)} ပိဿာ</strong></div>`).join('')}</details>`;}
function newStockRows(kind,id){const d=kind==='owned'?op().own:partyDraft(id);return d.rows.map(r=>`<article class="op69-stock-row"><div><strong>${esc(r.product)} · ${esc(r.grade)}</strong><p>${esc(W(r.warehouse))} · ${esc(r.batch)}</p><p>${vissText37(r.qty)} ပိဿာ${r.bags!==''?' · '+N(r.bags)+' အိတ်':''}${kind==='owned'?' · '+costText71(r):''}</p></div>${editable()?`<div class="row wrap">${button('ပြင်မယ်',`opening69Stock('${kind}','${id}','${r.id}')`)}${button('ဖယ်မယ်',`opening69RemoveStock('${kind}','${id}','${r.id}')`,'ghost')}</div>`:''}</article>`).join('')||`<p class="op69-empty">ထပ်ထည့်မည့် ကုန် မရှိသေးပါ။</p>`;}
function stockSection(kind,id){const d=kind==='owned'?op().own:partyDraft(id);const q=kind==='owned'?d.stock:d.answers.stock;return existingStock(kind,id)+question('stock',kind==='owned'?'စာရင်းမသွင်းရသေးတဲ့ ပွဲရုံပိုင်ကုန် ရှိပါသလား?':kind==='supplier'?'သူ့ပိုင်ကုန် ပွဲရုံမှာ ထပ်ထည့်ရန် ရှိပါသလား?':'သူဝယ်ပြီး မထုတ်ရသေးတဲ့ကုန် ထပ်ထည့်ရန် ရှိပါသလား?',q,`opening69StockAnswer.bind(null,'${kind}','${id}')`)+(q==='yes'?`<section class="card"><div class="row between wrap mb"><h3>ယခု ထပ်ထည့်မည့်ကုန်</h3>${editable()?button('ကုန်တစ်မျိုး ထည့်မယ်',`opening69Stock('${kind}','${id}')`,'primary','plus'):''}</div>${newStockRows(kind,id)}</section>`:'');}
function own(){return header('ပွဲရုံပိုင် စတင်လက်ကျန်','ကိုယ့်ပွဲရုံပိုင်ကုန်နဲ့ ငွေသိမ်းရာလက်ကျန်ကို ဖြည့်ပါ။')+back('သုံးပိုင်းရွေးရန်',"opening69View('home')")+`<div class="tabs"><button class="tab ${ui.tab==='stock'?'active':''}" onclick="opening69OwnTab('stock')">၁။ ကုန်လက်ကျန်</button><button class="tab ${ui.tab==='cash'?'active':''}" onclick="opening69OwnTab('cash')">၂။ ငွေလက်ကျန်</button></div>`+(ui.tab==='stock'?stockSection('owned','')+`<div class="op69-next">${button('ကုန်စာရင်း စစ်ပြီး · ငွေစာရင်း ဆက်ဖြည့်မယ်','opening69CheckOwn()','primary','arrow')}</div>`:cash())+footer();}
function cash(){const o=op(),list=state.masters.accounts.filter(canViewAccount68);return `<div class="row between wrap mb"><p class="small muted">ရှိပြီးသား အဖွင့်လက်ကျန်ကို ပြန်ပြထားပါသည်။ မှန်ကန်သောပမာဏ ဖြည့်ပြီး အမှန်ခြစ်ပါ။</p>${editable()&&state.role==='owner'?button('ငွေသိမ်းရာအသစ် ထည့်မယ်','opening69NewAccount()','secondary','plus'):''}</div><div class="op69-cash-grid">${list.map(a=>`<section class="card op69-account"><h3>${esc(a.name)}</h3><p class="field-help">လက်ရှိစာရင်းအရ ${cashText(bal(a.id))}</p>${money('စတင်လက်ကျန်','op69Cash_'+a.id,o.accounts[a.id].amount,`${readonly()} data-op69="cash" data-id="${esc(a.id)}"`)}<label class="account-permission68"><input type="checkbox" ${o.accounts[a.id].checked?'checked':''} data-op69="cash-check" data-id="${esc(a.id)}" ${readonly()}><span>ဒီအဖွင့်လက်ကျန် မှန်ပါတယ်</span></label></section>`).join('')}</div>${!list.length?note('ကြည့်ခွင့်ရှိသော ငွေသိမ်းရာမရှိပါ။ ပိုင်ရှင်က စစ်ပေးရန် လိုပါသည်။','blue'):''}<div class="op69-next">${button('ကုန်သည်စာရင်း ဆက်ဖြည့်မယ်',"opening69Scope('supplier')",'primary','arrow')}</div>`;}
function listParties(kind){const o=op();const all=state.masters.partners.filter(p=>p.kind===kind&&p.active!==false);return header(labels[kind]+' စတင်လက်ကျန်','အမည်နဲ့ရှာပြီး သက်ဆိုင်ရာ ကုန်နဲ့ငွေကျန်ကို ဖြည့်ပါ။')+back('သုံးပိုင်းရွေးရန်',"opening69View('home')")+`<div class="op69-toolbar"><div class="field"><label for="op69Search">အမည် / နေရပ် / ဖုန်း ရှာမယ်</label><input id="op69Search" type="search" placeholder="အမည် ရိုက်ရှာပါ" value="${esc(ui.search)}" oninput="opening69Search(this.value)"></div>${editable()?button(labels[kind]+'အသစ် ထည့်မယ်',`opening69NewParty('${kind}')`,'primary','plus'):''}</div><div class="v2-list" id="op69PartyList">${all.map(p=>partyRow(p)).join('')||empty('အမည်အသစ် ထည့်ပြီး စတင်နိုင်ပါသည်။','users')}</div><p id="op69SearchEmpty" class="op69-empty" hidden>ကိုက်ညီသောအမည် မရှိပါ။ အမည်အသစ် ထည့်နိုင်ပါသည်။</p><section class="card mt"><label class="account-permission68"><input type="checkbox" ${o.groups[kind]?'checked':''} data-op69="group" data-kind="${kind}" ${readonly()}><span>ဤ${labels[kind]}စာရင်းကို စစ်ပြီးပါပြီ။ မဖြည့်ထားသောအမည်များမှာ ထပ်ထည့်ရန် မရှိပါ။</span></label><p class="field-help">ရှိပြီးသားလက်ကျန်များကို ဆက်ထိန်းထားပါမည်။</p></section><div class="op69-next">${kind==='supplier'?button('ဝယ်သူစာရင်း ဆက်ဖြည့်မယ်',"opening69Scope('buyer')",'primary','arrow'):button('အားလုံး ပြန်စစ်မယ်',"opening69View('review')",'primary','eye')}</div>`+footer();}
function partyRow(p){const d=op().parties[p.id];const touched=d&&(Object.values(d.answers).some(x=>x)||d.rows.length);return `<div class="v3-partner-row op69-party" data-search="${esc(searchText(p.name+' '+p.locality+' '+p.phone))}"><span class="icon-box">${I('users')}</span><div class="grow"><strong>${esc(p.name)}</strong><p class="small muted">${esc(p.locality||'')} ${esc(p.phone||'')}</p><span class="pill ${d?.checked?'':touched?'blue':'gray'}">${d?.checked?'စစ်ပြီး':touched?'ဖြည့်နေဆဲ':'မဖြည့်ရသေး'}</span></div>${button(editable()?'ရွေးပြီး ဖြည့်မယ်':'ကြည့်မယ်',`opening69Party('${p.id}')`,'secondary','arrow')}</div>`;}
function existingMoney(p){const rows=[];if(p.kind==='supplier'){const dueAmount=sum(state.receipts.filter(r=>r.partnerId===p.id&&r.status==='purchased'),due);if(dueAmount)rows.push(['ပေးရန်',dueAmount]);const a=supplierBalance(p.id);if(a)rows.push(['ကြိုသုံးငွေ',a]);const l=sum((state.supplierLoans38||[]).filter(l=>l.partnerId===p.id),l=>loanBalance38(l).principal);if(l)rows.push(['ကြိုထုတ်ငွေအရင်း',l]);}else{const n=sum(state.sales.filter(s=>s.buyerId===p.id),receivable);if(n)rows.push(['ရရန်',n]);}return rows.length?`<div class="op69-existing"><strong>ရှိပြီးသား ငွေလက်ကျန်များ</strong>${rows.map(([k,n])=>row4(k,cashText(n))).join('')}<p class="field-help">ရှိပြီးသားကို ထပ်မထည့်ပါနှင့်။ အောက်တွင် စာရင်းမသွင်းရသေးသော ငွေကျန်ကိုသာ ဖြည့်ပါ။</p></div>`:'';}
function party(){const p=currentParty();if(!p)return listParties(ui.kind);const d=partyDraft(p.id);return header(p.name+' · စတင်လက်ကျန်',[labels[p.kind],p.locality,p.phone].filter(Boolean).join(' · '))+back(labels[p.kind]+' အမည်စာရင်းသို့',`opening69Scope('${p.kind}')`)+stockSection(p.kind,p.id)+existingMoney(p)+`<section class="card mt"><h3 class="mb">စာရင်းမသွင်းရသေးသော ငွေကျန်</h3>${moneyQuestions[p.kind].map(([key,q])=>{const a=d.answers[key],lock=key==='loan'&&state.role!=='owner';return `<section class="op69-money-question">${lock?`<p class="field-help">ကြိုထုတ်ငွေအဖွင့်ကို ပိုင်ရှင်က ဖြည့် / စစ်ပေးရပါမည်။</p>`:''}${question(key,q,a,`opening69MoneyAnswer.bind(null,'${p.id}','${key}')`)}${a==='yes'?`<div class="op69-money-inputs">${money(moneyNames[key]+' ပမာဏ','op69Value_'+key,d.values[key],`${readonly()} ${lock?'disabled':''} data-op69="party-money" data-key="${key}"`)}${key==='loan'?`<div class="field-row">${money('စတင်ရက်မတိုင်မီ အတိုးကျန်','op69LoanInterest',d.values.loanInterest,`${readonly()} ${lock?'disabled':''} data-op69="party-money" data-key="loanInterest"`)}${selectField('ဆက်တွက်မည့် လစဉ်အတိုးနှုန်း','op69LoanRate',[['3','3%'],['4','4%']],d.values.loanRate,`${readonly()} ${lock?'disabled':''} data-op69="party-money" data-key="loanRate"`)}</div><p class="field-help">ယခင်အတိုးကျန်ကို သီးခြားထည့်ပါ။ အတိုးအသစ်ကို Software စသုံးမည့်ရက်မှ ဆက်တွက်ပါမည်။</p>`:''}</div>`:''}</section>`;}).join('')}</section><div class="op69-next">${editable()?button('ဒီအမည်အတွက် စစ်ပြီး · သိမ်းမယ်','opening69CheckParty()','primary','check'):button('အမည်စာရင်းသို့',`opening69Scope('${p.kind}')`,'primary','back')}</div>`+footer();}
// V71: Opening-stock cost may be entered per viss or per standard bag.
// Native lot.cost remains cost per viss; preserve the entered basis separately.
function costForm71(f){
 const p=productBy(f.product);
 if(p&&f.costProduct71!==p.id){f.costStandardViss=p.standardViss||'';f.costProduct71=p.id;}
 f.costBasis??='viss';f.costInput??=f.cost??'';
 const bag=f.costBasis==='bag';
 return `<section id="op71CostFields"><div class="field-row">${selectField('ဝယ်ရင်းဈေးတွက်နည်း','op71CostBasis',[['viss','တစ်ပိဿာဈေး'],['bag','တစ်စံအိတ်ဈေး']],f.costBasis,'data-op69="stock" data-key="costBasis" onchange="opening71BasisChanged()"')}${money('ဝယ်ရင်းနှုန်း','op69Cost',f.costInput,'data-op69="stock" data-key="costInput" oninput="opening71CostPreview()"')}</div><p class="field-help">${bag?'တစ်စံအိတ်လျှင် ကျသင့်ငွေကို ဖြည့်ပါ။':'တစ်ပိဿာလျှင် ကျသင့်ငွေကို ဖြည့်ပါ။'}</p>${bag?field('တစ်စံအိတ်ဝင် ပိဿာ','op71StandardViss',{value:f.costStandardViss??'',type:'number',min:.01,max:1000000000,step:.01,required:true,suffix:'ပိဿာ',extra:'data-op69="stock" data-key="costStandardViss" oninput="opening71CostPreview()"'}):''}<div id="op71CostPreview" class="summary-box mb mt" aria-live="polite"></div></section>`;
}
function costText71(r){return r.costBasis==='bag'?'ဝယ်ရင်း '+cashText(r.costInput)+' / တစ်စံအိတ် ('+vissText37(r.costStandardViss)+' ပိဿာ)':'ဝယ်ရင်း '+cashText(r.costInput??r.cost)+' / တစ်ပိဿာ';}
window.opening71BasisChanged=function(){const f=ui.stockForm;if(!f||!mutate())return;f.costBasis=value('op71CostBasis');f.costInput=value('op69Cost');if(document.getElementById('op71StandardViss'))f.costStandardViss=value('op71StandardViss');if(f.costBasis==='bag'&&(f.costStandardViss==null||f.costStandardViss===''))f.costStandardViss=productBy(value('op69Product'))?.standardViss||'';const root=document.getElementById('op71CostFields');if(root)root.outerHTML=costForm71(f);op().pendingStock=copy(f);saveDraft();opening71CostPreview();};
window.opening71CostPreview=function(){const root=document.getElementById('op71CostPreview');if(!root)return;const qty=number('op69Qty'),price=number('op69Cost'),basis=value('op71CostBasis'),standard=basis==='bag'?number('op71StandardViss'):1;if(!(qty>0)||!Number.isFinite(price)||price<0||!(standard>0)||!Number.isFinite(standard)){root.textContent='အလေးချိန်၊ ဝယ်ရင်းနှုန်းနှင့် လိုအပ်လျှင် စံအိတ်ဝင်ပိဿာ ဖြည့်ပါ။';return;}const rate=price/standard,total=qty*rate;root.innerHTML=(basis==='bag'?row4('စံအိတ်ဝင်',vissText37(standard)+' ပိဿာ / အိတ်')+row4('အလေးချိန်အရ စံအိတ်နှင့်ညီမျှအရေအတွက်',new Intl.NumberFormat('en-US',{maximumFractionDigits:6}).format(qty/standard)+' အိတ်'):'')+row4('ဝယ်ရင်းစုစုပေါင်း',cashText(total))+`<p class="field-help">${basis==='bag'?'စုစုပေါင်းပိဿာ ÷ တစ်စံအိတ်ဝင်ပိဿာ × တစ်စံအိတ်ဈေး':'စုစုပေါင်းပိဿာ × တစ်ပိဿာဈေး'}${basis==='bag'?'။ အိတ်အရေအတွက် (သိလျှင်) ကွက်ကို ဈေးတွက်ရာတွင် မသုံးပါ။':''}</p>`;};
function stockForm(){const f=ui.stockForm,kind=f.kind;return header(labels[kind]+' · ကုန်တစ်မျိုး ထည့်မယ်','ကုန်အမည်၊ တကယ်ရှိပိဿာနဲ့ ဂိုဒေါင်ကို ဖြည့်ပါ။')+back('ပြန်မယ်','opening69ReturnStock()')+`<form id="op69StockForm" onsubmit="event.preventDefault();opening69SaveStock()" class="card">${field('ကုန်အမည်','op69Product',{value:f.product,required:true,extra:'list="op69Products" data-op69="stock" data-key="product" onchange="opening69StockProduct(this.value)"'})}<div class="op69-inline-add">${button('ကုန်အသစ် ထည့်မယ်','opening69NewProduct()','secondary','plus')}</div><datalist id="op69Products">${products(true).map(p=>`<option value="${esc(p.name)}"></option>`).join('')}</datalist><div class="field-row">${selectField('အဆင့်','op69Grade',(productBy(f.product)?.grades||['A','B','C']).map(g=>[g,g]),f.grade,'data-op69="stock" data-key="grade"')}${selectField('ကုန်ရှိသော ဂိုဒေါင်','op69Warehouse',whOpts(),f.warehouse,'data-op69="stock" data-key="warehouse"')}</div><div class="field-row">${field('စုစုပေါင်း ပိဿာအလေးချိန်','op69Qty',{value:f.qty,type:'number',min:.01,step:.01,required:true,suffix:'ပိဿာ',extra:'data-op69="stock" data-key="qty"'})}${field('အိတ်အရေအတွက် (သိလျှင်)','op69Bags',{value:f.bags,type:'number',min:0,step:1,extra:'data-op69="stock" data-key="bags"'})}</div>${kind==='owned'?costForm71(f)+selectField('မူရင်းကုန်သည် (သိလျှင်)','op69Origin',[['','မူရင်းကုန်သည် မသိပါ'],...partners('supplier').map(p=>[p.id,supplierLabel(p)])],f.originPartnerId,'data-op69="stock" data-key="originPartnerId"'):''}<details class="op69-existing"><summary>အသုတ်အမှတ် / မှတ်ချက်</summary>${field('အသုတ်အမည်','op69Batch',{value:f.batch,required:true,extra:'maxlength="60" data-op69="stock" data-key="batch"'})}${field('မှတ်ချက်','op69Note',{value:f.note,extra:'maxlength="300" data-op69="stock" data-key="note"'})}</details><div class="op69-form-actions">${button('မူကြမ်း သိမ်းပြီး ပြန်မယ်','opening69SaveStock()','primary','check')}</div></form>`+footer();}
function newPartyForm(){return header(labels[ui.kind]+'အသစ် ထည့်မယ်','အမည်သိမ်းပြီးရင် စတင်လက်ကျန်ကို ဆက်ဖြည့်နိုင်ပါမယ်။')+back('အမည်စာရင်းသို့',`opening69Scope('${ui.kind}')`)+`<form id="op69NewPartyForm" data-kind="${ui.kind}" class="card" onsubmit="event.preventDefault();opening69CreateParty()">${field('အမည်','op69PartyName',{required:true,extra:'maxlength="80"'})}${field('နေရပ် / မြို့နယ်','op69PartyLocality',{required:true,extra:'maxlength="100"'})}${field('ဖုန်းနံပါတ်','op69PartyPhone',{extra:'maxlength="30" inputmode="tel"'})}<div class="op69-form-actions">${button('အမည်သိမ်းပြီး လက်ကျန်ဆက်ဖြည့်မယ်','opening69CreateParty()','primary','arrow')}</div></form>`+footer();}
function newAccountForm(){return header('ငွေသိမ်းရာအသစ် ထည့်မယ်','ပွဲရုံငွေသား၊ ဘဏ် သို့မဟုတ် Wallet ကို အမည်ပေးပါ။')+back('ငွေလက်ကျန်သို့',"opening69OwnTab('cash')")+`<form id="op69NewAccountForm" class="card" onsubmit="event.preventDefault();opening69CreateAccount()">${field('ငွေသိမ်းရာအမည်','op69AccountName',{required:true,extra:'maxlength="60"'})}${selectField('အမျိုးအစား','op69AccountType',[['bank','Bank Account'],['cash','Cash Account'],['wallet','Wallet / Mobile Money']],'bank')}${money('စတင်လက်ကျန်','op69AccountAmount',0)}${accountPermissionField68('op69AccountVisible',true)}<p class="field-help">အဖွင့်ငွေကို မူကြမ်းသိမ်းထားပြီး ပိုင်ရှင်အတည်ပြုမှ စာရင်းထဲ ထည့်ပါမည်။</p><div class="op69-form-actions">${button('သိမ်းပြီး ငွေစာရင်းသို့','opening69CreateAccount()','primary','check')}</div></form>`+footer();}
function newProductForm(){return header('ကုန်အသစ် ထည့်မယ်','ကုန်အမည် သိမ်းပြီး အဖွင့်ကုန်လိုင်းကို ဆက်ဖြည့်နိုင်ပါမယ်။')+back('ကုန်လိုင်းသို့ ပြန်မယ်',"opening69View('stock')")+`<form id="op69NewProductForm" class="card" onsubmit="event.preventDefault();opening69CreateProduct()">${field('ကုန်အမည်','op69NewProductName',{value:ui.stockForm?.product||'',required:true,extra:'maxlength="60"'})}${field('အဆင့်များ','op69NewProductGrades',{value:'A, B, C',required:true,help:'အဆင့်တစ်ခုနှင့်တစ်ခုကို ကော်မာ (,) ဖြင့် ခွဲပါ။'})}${field('တစ်အိတ်စံပိဿာ (သိလျှင်)','op69NewProductStandard',{type:'number',min:.01,step:.01,value:'',suffix:'ပိဿာ'})}<div class="op69-form-actions">${button('ကုန်အမည်သိမ်းပြီး ဆက်ဖြည့်မယ်','opening69CreateProduct()','primary','arrow')}</div></form>`+footer();}
window.opening69NewProduct=function(){if(!mutate())return;ui.view='newproduct';render();};
window.opening69CreateProduct=function(){if(!mutate()||!validForm('op69NewProductForm'))return;const name=cleanText(value('op69NewProductName')),grades=[...new Set(value('op69NewProductGrades').split(/[,၊]/).map(cleanText).filter(Boolean))],standard=value('op69NewProductStandard');if(!safeLabel(name)||products().some(p=>searchText(p.name)===searchText(name))||!grades.length||grades.some(g=>!safeLabel(g))||grades.length>20)return inform('ကုန်အမည်အသစ်နှင့် အဆင့်များကို မှန်ကန်စွာ ဖြည့်ပါ။ အမည်တူ မရပါ။');if(standard!==''&&(!(Number(standard)>0)||!Number.isFinite(Number(standard))||Math.abs(Number(standard)*100-Math.round(Number(standard)*100))>.000001))return inform('တစ်အိတ်စံပိဿာကို မှန်ကန်စွာ ဖြည့်ပါ။');const p={id:uid('P'),name,grades,standardViss:standard===''?null:Number(standard),active:true,revision:1,aliases:[]};state.masters.products.push(p);syncMasters();masterLog('product',p.id,null,p);ui.stockForm.product=name;ui.stockForm.grade=grades[0];op().pendingStock=copy(ui.stockForm);saveDraft();ui.view='stock';render();};
function failures(){const o=op(),out=[];if(!dateOK(o.startDate)||Number(o.startDate.slice(0,4))<1900)out.push(['home','စသုံးမည့်ရက်ကို မှန်ကန်စွာ ဖြည့်ပါ။']);if(o.pendingStock)out.push(['stockdraft','မသိမ်းရသေးသော ကုန်လိုင်းမူကြမ်းကို ဆက်ဖြည့်ပါ သို့မဟုတ် ဖယ်ပါ။']);if(!o.own.checked)out.push(['own','ပွဲရုံပိုင် ကုန်စာရင်း စစ်ပြီးကြောင်း သတ်မှတ်ပါ။']);for(const a of state.masters.accounts){const d=o.accounts[a.id];if(!a.active&&Number(d?.amount)>0)out.push(['cash',state.role==='owner'||canViewAccount68(a)?a.name+' ကို အသုံးပြုမည် (Active) ပြောင်းပြီးမှ အဖွင့်ငွေထည့်ပါ။':'ပိုင်ရှင် စစ်ပေးရန်ကျန်သော ငွေသိမ်းရာရှိပါသည်။']);if(!d?.checked||!validMoney(d.amount))out.push(['cash',state.role==='owner'||canViewAccount68(a)?a.name+' ငွေလက်ကျန်ကို စစ်ပါ။':'ပိုင်ရှင် စစ်ပေးရန်ကျန်သော ငွေသိမ်းရာရှိပါသည်။']);}for(const k of ['supplier','buyer']){if(!o.groups[k])out.push([k,labels[k]+' အုပ်စုကို စစ်ပြီးကြောင်း အမှန်ခြစ်ပါ။']);for(const [id,d] of Object.entries(o.parties)){const p=supplierBy(id);if(p?.kind===k&&touched(d)&&!d.checked)out.push([k,p.name+' အတွက် ဖြည့်နေဆဲစာရင်းကို ပြန်စစ်ပါ။']);}}return out;}
function touched(d){return d.rows.length||Object.values(d.answers).some(x=>x!==null&&x!==undefined);}
function validMoney(v){return v!==''&&v!==null&&v!==undefined&&Number.isSafeInteger(Number(v))&&Number(v)>=0;}
function stockValid(kind,id){const d=kind==='owned'?op().own:partyDraft(id);const a=kind==='owned'?d.stock:d.answers.stock;if(!['yes','no'].includes(a))return 'ကုန်လက်ကျန် ရှိ / မရှိ ရွေးပါ။';if(a==='yes'&&!d.rows.length)return 'ရှိသည်ဟု ရွေးထားပါက ကုန်တစ်မျိုး အနည်းဆုံး ထည့်ပါ။';return '';}
function partyValid(id){const p=supplierBy(id),d=partyDraft(id);let err=stockValid(p.kind,id);if(err)return err;for(const [k] of moneyQuestions[p.kind]){if(!['yes','no'].includes(d.answers[k]))return moneyNames[k]+' ရှိ / မရှိ ရွေးပါ။';if(d.answers[k]==='yes'&&(!validMoney(d.values[k])||Number(d.values[k])<=0))return moneyNames[k]+' ပမာဏကို သုညထက်ကြီးသော ကျပ်ငွေဖြင့် ဖြည့်ပါ။';}if(d.answers.loan==='yes'&&(!validMoney(d.values.loanInterest)||!openingLoanRateValid(d.values.loanRate)))return 'ကြိုထုတ်ငွေ အတိုးကျန်နှင့် လစဉ်နှုန်းကို ပြန်စစ်ပါ။';return '';}
function activeRows(){const o=op();return [...(o.own.stock==='yes'?o.own.rows.map(r=>({...r,kind:'owned',partyId:''})):[]),...Object.entries(o.parties).flatMap(([id,d])=>d.answers.stock==='yes'?d.rows.map(r=>({...r,kind:supplierBy(id)?.kind,partyId:id})):[])];}
function balancesDraft(){return Object.entries(op().parties).flatMap(([id,d])=>moneyQuestions[supplierBy(id)?.kind]?.filter(([k])=>d.answers[k]==='yes').map(([k])=>({partnerId:id,type:k,amount:Number(d.values[k])||0}))||[]);}
function review(){const o=op(),bad=failures();const accs=state.masters.accounts.filter(canViewAccount68),rows=activeRows(),moneyRows=balancesDraft();return header(o.status==='approved'?'စတင်လက်ကျန် အတည်ပြုပြီးပါပြီ':'အားလုံး ပြန်စစ်မယ်','မှားနေသောအပိုင်းကို “ပြင်မယ်” နှိပ်ပြီး ပြန်ပြင်နိုင်ပါသည်။')+back('သုံးပိုင်းရွေးရန်',"opening69View('home')")+`<section class="card mb"><div class="row between wrap"><div><h3>စသုံးမည့်ရက် — ${dateOK(o.startDate)?shortDate(o.startDate):'ရက်ရွေးရန် လိုသည်'}</h3><p class="small muted">${dateOK(o.startDate)?shortDate(prevDate(o.startDate)):''} အဆုံးရှိ လက်ကျန်</p></div>${editable()?button('ရက် ပြင်မယ်',"opening69View('home')"):''}</div></section>${o.status==='approved'?`<div class="mb">${note('ဤအဖွင့်စာရင်းကို တစ်ကြိမ်သာ ထည့်ပြီးပါပြီ။ ကုန်လက်ကျန်၊ ငွေစာရင်းနှင့် တစ်ဦးချင်းစာရင်းတွင် ဆက်အသုံးပြုနိုင်ပါသည်။','blue')}</div>`:bad.length?`<section class="op69-pending"><h3>ပြန်စစ်ရန် ကျန်သည် · ${bad.length} ချက်</h3>${bad.map(([k,t])=>`<button class="op69-pending-row" onclick="opening69Fix('${k}')"><span>${esc(t)}</span>${I('arrow')}</button>`).join('')}</section>`:`<div class="mb">${note('အချက်အလက်များ ဖြည့်ပြီးပါပြီ။ ပိုင်ရှင်က အောက်ပါအနှစ်ချုပ်ကို စစ်ပြီး အတည်ပြုနိုင်ပါသည်။','blue')}</div>`}<section class="card mb"><div class="row between wrap mb"><h3>ငွေသိမ်းရာ စတင်လက်ကျန်</h3>${editable()?button('ပြင်မယ်',"opening69OwnTab('cash')"):''}</div>${accs.map(a=>row4(esc(a.name),cashText(o.accounts[a.id].amount))).join('')}${row4('ကြည့်ခွင့်ရှိသော ငွေသိမ်းရာ စုစုပေါင်း',cashText(sum(accs,a=>o.accounts[a.id].amount)))}</section>${['owned','supplier','buyer'].map(k=>{const stocks=rows.filter(r=>r.kind===k);return `<section class="card mb"><div class="row between wrap mb"><h3>${labels[k]} · ယခု ထပ်ထည့်မည့်ကုန်</h3>${editable()?button('ပြင်မယ်',`opening69Scope('${k}')`):''}</div>${stocks.length?stocks.map(r=>`<div class="op69-line"><div><strong>${esc(r.product)} · ${esc(r.grade)}</strong><p class="small muted">${k==='owned'?'ပွဲရုံပိုင်':esc(supplierLabel(supplierBy(r.partyId)))} · ${esc(W(r.warehouse))} · ${esc(r.batch)}</p>${k==='owned'?`<p class="small muted">${costText71(r)} · စုစုပေါင်း ${cashText(r.qty*r.cost)}</p>`:''}</div><strong>${vissText37(r.qty)} ပိဿာ</strong></div>`).join(''):'<p class="small muted">ထပ်ထည့်မည့်ကုန် မရှိပါ။</p>'}${stocks.length?row4('ထပ်ထည့်မည့်ပိဿာ စုစုပေါင်း',vissText37(sum(stocks,r=>r.qty))+' ပိဿာ'):''}</section>`;}).join('')}<section class="card mb"><h3 class="mb">တစ်ဦးချင်း ယခု ထပ်ထည့်မည့် ငွေကျန်</h3>${moneyRows.map(r=>`<div class="op69-line"><div><strong>${esc(supplierLabel(supplierBy(r.partnerId)))}</strong><p class="small muted">${moneyNames[r.type]}${r.type==='loan'?' · ယခင်အတိုး '+cashText(o.parties[r.partnerId].values.loanInterest):''}</p></div><strong>${cashText(r.amount)}</strong>${editable()?button('ပြင်မယ်',`opening69Party('${r.partnerId}')`):''}</div>`).join('')||'<p class="small muted">ထပ်ထည့်မည့် ငွေကျန် မရှိပါ။</p>'}</section>${o.status==='approved'?approvedActions():state.role!=='owner'?note('မူကြမ်း သိမ်းထားပါသည်။ ပိုင်ရှင်အကောင့်မှ စစ်ပြီး အတည်ပြုရပါမည်။','blue'):`<section class="card op69-confirm"><label class="account-permission68"><input id="op69Confirm" type="checkbox" ${bad.length?'disabled':''}><span>အထက်ပါ ကုန်၊ ငွေ၊ ပေးရန်နှင့် ရရန်တို့ကို စစ်ဆေးပြီး မှန်ကန်ကြောင်း အတည်ပြုပါသည်။</span></label>${button('စတင်လက်ကျန် အတည်ပြုမယ်','opening69Approve()','primary','check')}</section>`}${o.revisions.length?`<details class="op69-existing"><summary>အတည်ပြု / ပြင်ဆင်မှုမှတ်တမ်း (${o.revisions.length})</summary>${o.revisions.map(r=>`<p class="small">${esc(r.at)} · ${esc(r.action)}${r.reason?' · '+esc(r.reason):''}</p>`).join('')}</details>`:''}`+footer();}
function approvedActions(){return `<div class="op69-next">${button('ကုန်လက်ကျန် ကြည့်မယ်',"navigate('inventory')",'secondary','stock')}${button('ငွေစာရင်း ကြည့်မယ်',"navigate('cash')",'primary','wallet')}${state.role==='owner'?button('အဖွင့်စာရင်း ပြင်ရန် ပြန်ဖွင့်မယ်','opening69ReopenForm()','secondary'):''}</div>`;}
function page69(){op();return ({home,own,parties:()=>listParties(ui.kind),party,stock:stockForm,newparty:newPartyForm,newaccount:newAccountForm,newproduct:newProductForm,review})[ui.view]?.()||home();}
window.openInitial69=function(){ui.view=op().status==='approved'?'review':'home';ui.search='';beginSetup('opening69');};
window.opening69View=function(v){ui.view=v;render();window.scrollTo({top:0,behavior:'instant'});};
window.opening69Scope=function(k){ui.kind=k;ui.search='';ui.view=k==='owned'?'own':'parties';ui.tab='stock';render();window.scrollTo({top:0,behavior:'instant'});};
window.opening69OwnTab=function(t){ui.kind='owned';ui.view='own';ui.tab=t;render();};
window.opening69Fix=function(k){if(k==='stockdraft')opening69ResumeStock();else if(k==='home')opening69View('home');else if(k==='own')opening69Scope('owned');else if(k==='cash')opening69OwnTab('cash');else opening69Scope(k);};
window.opening69Search=function(v){ui.search=v;let n=0;document.querySelectorAll('.op69-party').forEach(r=>{r.hidden=!r.dataset.search.includes(searchText(v));if(!r.hidden)n++;});document.getElementById('op69SearchEmpty').hidden=n>0;};
window.opening69SaveDraft=function(){saveDraft();toast(storageOK?'မူကြမ်း သိမ်းပြီးပါပြီ။':'မူကြမ်း သိမ်းမရပါ။',!storageOK);};
window.opening69StockAnswer=function(kind,id,a){if(!mutate())return;const d=kind==='owned'?op().own:partyDraft(id);if(a==='no'&&d.rows.length)return inform('ထည့်ထားသောကုန်များ ရှိပါသည်။ မရှိပါ ရွေးလိုလျှင် ကုန်လိုင်းများကို အရင်ဖယ်ပါ။');if(kind==='owned')d.stock=a;else d.answers.stock=a;d.checked=false;saveDraft();render();};
window.opening69MoneyAnswer=function(id,k,a){if(!mutate())return;const d=partyDraft(id);if(k==='loan'&&state.role!=='owner'&&(a==='yes'||d.answers.loan==='yes'))return inform('ကြိုထုတ်ငွေအဖွင့်ကို ပိုင်ရှင်က ဖြည့်ပေးပါ။');d.answers[k]=a;d.checked=false;saveDraft();render();};
window.opening69Party=function(id){const p=supplierBy(id);if(!p)return;ui.party=id;ui.kind=p.kind;partyDraft(id);ui.view='party';render();window.scrollTo({top:0,behavior:'instant'});};
window.opening69CheckOwn=function(){if(!mutate())return;const err=stockValid('owned','');if(err)return inform(err);op().own.checked=true;saveDraft();opening69OwnTab('cash');};
window.opening69CheckParty=function(){if(!mutate())return;const err=partyValid(ui.party);if(err)return inform(err);partyDraft(ui.party).checked=true;op().groups[ui.kind]=false;saveDraft();opening69Scope(ui.kind);toast('ဒီအမည်အတွက် မူကြမ်း စစ်ပြီး သိမ်းထားပါပြီ။');};
window.opening69Stock=function(kind,id='',row=''){if(!mutate())return;const d=kind==='owned'?op().own:partyDraft(id),old=d.rows.find(r=>r.id===row);ui.stockForm=old?{...old,kind,partyId:id}:{id:uid('OPROW'),kind,partyId:id,product:'',grade:'A',warehouse:whOpts()[0]?.[0]||'',qty:'',bags:'',cost:'',originPartnerId:'',batch:'စတင်ကုန်-'+(d.rows.length+1),note:''};ui.view='stock';op().pendingStock=copy(ui.stockForm);saveDraft();render();};
window.opening69StockProduct=function(name){const p=productBy(name);if(ui.stockForm?.kind==='owned'){ui.stockForm.product=name;const root=document.getElementById('op71CostFields');if(root)root.outerHTML=costForm71(ui.stockForm);op().pendingStock=copy(ui.stockForm);saveDraft();opening71CostPreview();}if(p&&!p.grades.includes(value('op69Grade'))){const el=document.getElementById('op69Grade');el.innerHTML=p.grades.map(g=>`<option>${esc(g)}</option>`).join('');ui.stockForm.grade=p.grades[0];}else if(p){const el=document.getElementById('op69Grade'),selected=el.value;el.innerHTML=p.grades.map(g=>`<option ${g===selected?'selected':''}>${esc(g)}</option>`).join('');}};
window.opening69ReturnStock=function(){const f=ui.stockForm;if(f?.kind==='owned')opening69Scope('owned');else if(f)opening69Party(f.partyId);else opening69View('home');};
window.opening69SaveStock=function(){if(!mutate()||!validForm('op69StockForm'))return;const f=ui.stockForm,p=productBy(value('op69Product')),wh=state.warehouses.find(w=>w.id===value('op69Warehouse')&&w.active),qty=number('op69Qty'),bags=value('op69Bags'),costInput=f.kind==='owned'?number('op69Cost'):0,costBasis=f.kind==='owned'?value('op71CostBasis'):'viss',costStandardViss=costBasis==='bag'?number('op71StandardViss'):null,cost=f.kind==='owned'?costInput/(costBasis==='bag'?costStandardViss:1):0,grade=value('op69Grade'),batch=cleanText(value('op69Batch'));if(!p?.active||!wh||!p.grades.includes(grade)||!(qty>0)||!Number.isFinite(qty)||Math.abs(qty*100-Math.round(qty*100))>.000001||qty>1000000000)return inform('ကုန်အမည်၊ အဆင့်၊ ဂိုဒေါင်နှင့် ပိဿာအလေးချိန်ကို ပြန်စစ်ပါ။');if(bags!==''&&(!Number.isSafeInteger(Number(bags))||Number(bags)<0))return inform('အိတ်အရေအတွက်ကို သုည သို့မဟုတ် အပေါင်းကိန်းပြည့်ဖြင့် ဖြည့်ပါ။');if(f.kind==='owned'&&(!['viss','bag'].includes(costBasis)||!validMoney(costInput)))return inform('ဝယ်ရင်းဈေးတွက်နည်းနှင့် ဝယ်ရင်းနှုန်းကို ကျပ်ငွေဖြင့် ဖြည့်ပါ။');if(f.kind==='owned'&&costBasis==='bag'&&(!Number.isFinite(costStandardViss)||costStandardViss<=0||costStandardViss>1000000000||Math.abs(costStandardViss*100-Math.round(costStandardViss*100))>.000001))return inform('တစ်စံအိတ်ဝင် ပိဿာကို သုညထက်ကြီးသော အလေးချိန်ဖြင့် ဖြည့်ပါ။');if(!Number.isFinite(cost)||!Number.isFinite(qty*cost)||qty*cost>Number.MAX_SAFE_INTEGER)return inform('ဝယ်ရင်းတန်ဖိုးသည် သတ်မှတ်နိုင်သော ပမာဏထက် ကျော်နေပါသည်။');if(!safeLabel(batch))return inform('အသုတ်အမည်ကို မှန်ကန်စွာ ဖြည့်ပါ။');const d=f.kind==='owned'?op().own:partyDraft(f.partyId);if(d.rows.some(r=>r.id!==f.id&&r.product===p.name&&r.grade===grade&&r.warehouse===wh.id&&searchText(r.batch)===searchText(batch)))return inform('တူညီသော ကုန်၊ အဆင့်၊ ဂိုဒေါင်နှင့် အသုတ် ရှိပြီးသားဖြစ်သည်။ ရှိပြီးသားကုန်လိုင်းကို ပြင်ပါ သို့မဟုတ် အသုတ်အမည်ခွဲပါ။');const row={id:f.id,product:p.name,productId:p.id,grade,warehouse:wh.id,qty,bags:bags===''?'':Number(bags),cost,costInput,costBasis,costStandardViss,costProduct71:p.id,originPartnerId:value('op69Origin'),batch,note:cleanText(value('op69Note'))};const i=d.rows.findIndex(r=>r.id===f.id);if(i>=0)d.rows[i]=row;else d.rows.push(row);d.checked=false;if(f.kind==='owned')d.stock='yes';else d.answers.stock='yes';delete op().pendingStock;saveDraft();ui.stockForm=null;if(f.kind==='owned')opening69Scope('owned');else opening69Party(f.partyId);toast('ကုန်လိုင်းကို မူကြမ်း သိမ်းထားပါပြီ။');};
window.opening69RemoveStock=function(kind,id,row){if(!mutate())return;const d=kind==='owned'?op().own:partyDraft(id);d.rows=d.rows.filter(r=>r.id!==row);d.checked=false;saveDraft();render();};
window.opening69NewParty=function(kind){if(!mutate())return;ui.kind=kind;ui.view='newparty';render();};
window.opening69CreateParty=function(){if(!mutate()||!validForm('op69NewPartyForm'))return;const name=cleanText(value('op69PartyName')),locality=cleanText(value('op69PartyLocality')),phone=cleanText(value('op69PartyPhone'));if(!name||!locality||/[<>]/.test(name+locality+phone))return inform('အမည်နှင့် နေရပ်ကို မှန်ကန်စွာ ဖြည့်ပါ။');if(matchingPartner(name,locality,ui.kind,''))return inform('ဤအမည်နှင့် နေရပ်တူသော စာရင်း ရှိပြီးသားဖြစ်သည်။');const p={id:uid('C'),name,locality,phone,kind:ui.kind,type:ui.kind==='buyer'?'buyer':'trader',active:true};state.masters.partners.push(p);op().groups[ui.kind]=false;masterLog('partner',p.id,null,p);saveDraft();opening69Party(p.id);};
window.opening69NewAccount=function(){if(!mutate()||state.role!=='owner')return;ui.view='newaccount';render();};
window.opening69CreateAccount=function(){if(!mutate()||state.role!=='owner'||!validForm('op69NewAccountForm'))return;const name=cleanText(value('op69AccountName')),type=value('op69AccountType'),amount=value('op69AccountAmount');if(!safeLabel(name)||state.masters.accounts.some(a=>searchText(a.name)===searchText(name)))return inform('ငွေသိမ်းရာအမည် မှန်ကန်စွာ ဖြည့်ပါ။ အမည်တူ မရပါ။');if(!['bank','cash','wallet'].includes(type)||!validMoney(amount))return inform('အမျိုးအစားနှင့် စတင်လက်ကျန်ကို ပြန်စစ်ပါ။');const a={id:uid('ACC'),name,type,active:true,pendingOpening69:true,staffCanView:document.getElementById('op69AccountVisible').checked};state.masters.accounts.push(a);state.bases[a.id]=0;op().accounts[a.id]={amount:Number(amount),checked:true};syncMasters();masterLog('account',a.id,null,a);saveDraft();opening69OwnTab('cash');};
// Single-field draft persistence; never posts stock or cash while typing.
document.addEventListener('input',capture);document.addEventListener('change',capture);
function capture(e){const el=e.target,key=el.dataset?.op69;if(!key||!el.closest('#opening69')||!editable())return;const o=op();if(key==='start'){o.startDate=el.value;const hint=document.querySelector('.op69-date .field-help');if(hint)hint.textContent=(dateOK(el.value)?shortDate(prevDate(el.value)):'—')+' အဆုံးရှိ လက်ကျန်များကို ထည့်ပါ။ နေ့တိုင်းစစ်သော နေ့ဖွင့်ငွေနှင့် သီးခြားဖြစ်သည်။';saveDraft();return;}if(key==='cash'||key==='cash-check'){const a=state.masters.accounts.find(a=>a.id===el.dataset.id);if(!canViewAccount68(a))return;o.accounts[a.id][key==='cash'?'amount':'checked']=key==='cash'?el.value:el.checked;if(key==='cash'){o.accounts[a.id].checked=false;const c=el.closest('.op69-account')?.querySelector('[data-op69="cash-check"]');if(c)c.checked=false;}}else if(key==='party-money'){if(el.dataset.key.startsWith('loan')&&state.role!=='owner')return;const d=partyDraft(ui.party);d.values[el.dataset.key]=el.value;d.checked=false;o.groups[ui.kind]=false;}else if(key==='group')o.groups[el.dataset.kind]=el.checked;else if(key==='stock'&&ui.stockForm){ui.stockForm[el.dataset.key]=el.value;o.pendingStock=copy(ui.stockForm);}if(key==='stock'&&ui.stockForm?.kind==='owned')opening71CostPreview();saveDraft();}
