window.opening69SaveDispatch=function(id){if(!guardWork()||!validForm('op69DispatchForm'))return;const l=buyerOpeningLots().find(l=>l.id===id),qty=number('op69DispatchQty'),date=value('op69DispatchDate');if(!l||!Number.isFinite(qty)||qty<=0||qty>l.qty||Math.abs(qty*100-Math.round(qty*100))>.000001||!dateOK(date)||date<op().startDate||date>today())return error('ရက်စွဲနှင့် ထုတ်ပေးနိုင်သော ပိဿာကို ပြန်စစ်ပါ။');takeLot4(l,qty);op().dispatches.push({id:uid('OPDIS'),lotId:id,buyerId:l.buyerId,product:l.product,grade:l.grade,date,qty,warehouse:l.warehouse,batch:l.batch});state.moves.push({product:l.product,grade:l.grade,qty,bags:0,direction:'out',ref:l.originReceiptNo||l.batch,date,kind:'opening-dispatch69'});audit4(l.name+' ၏ စတင်လက်ကျန်ကုန် '+vissText37(qty)+' ပိဿာ ထုတ်ပေးခဲ့သည်။');done4('ဝယ်သူပိုင်ကုန် ထုတ်ပေးပြီးပါပြီ။ အရောင်းအသစ် မတင်ထားပါ။','inventory');};
function reopenBlock(){const o=op(),r=o.posted;if(!r)return 'အတည်ပြုမှတ်တမ်း မရှိပါ။';if(state.transactions.length!==r.txnCount||state.moves.length!==r.moveCount||state.day!==o.startDate||state.closed||op().balances.some(b=>b.payments.length)||op().dispatches.length)return 'အဖွင့်စာရင်းကို အသုံးပြုပြီး နေ့စဉ်လုပ်ငန်း ရှိနေပါပြီ။ လက်ကျန်ပြင်ဆင်မှုအဖြစ် သီးခြား ဆောင်ရွက်ပါ။';if(r.lots.some(x=>{const l=state.lots.find(l=>l.id===x.id);return !l||l.qty!==x.qty;})||state.lots.some(l=>l.opening69===r.run&&!r.lots.some(x=>x.id===l.id)))return 'အဖွင့်ကုန်ကို ရောင်းခြင်း၊ ထုပ်ပိုးခြင်း သို့မဟုတ် ရွှေ့ခြင်းတွင် အသုံးပြုပြီးဖြစ်သည်။';if(r.receipts.some(x=>state.receipts.find(y=>y.id===x.id)?.status!==x.status)||r.advances.some(id=>state.partnerAdvances.find(a=>a.id===id)?.allocations?.length)||r.loans.some(id=>(state.supplierLoans38||[]).find(l=>l.id===id)?.payments?.length))return 'အဖွင့်ကုန် / ကြိုငွေကို ဆက်လက်အသုံးပြုပြီးဖြစ်သည်။';return '';}
window.opening69ReopenForm=function(){if(state.role!=='owner'||op().status!=='approved')return;const blocked=reopenBlock();if(blocked)return toast(blocked,true);openModal('အဖွင့်စာရင်း ပြင်ရန် ပြန်ဖွင့်မယ်','အသုံးမပြုရသေးသော အဖွင့်စာရင်းကိုသာ မူကြမ်းပြန်ဖွင့်နိုင်ပါသည်။',`<form id="op69ReopenForm" onsubmit="event.preventDefault();opening69Reopen()">${field('ပြန်ပြင်လိုသည့် အကြောင်းပြချက်','op69ReopenReason',{required:true,extra:'maxlength="300"'})}</form>`,button('မလုပ်တော့ပါ','closeModal()')+button('အကြောင်းပြချက်နှင့် ပြန်ဖွင့်မယ်','opening69Reopen()','primary','check'));};
window.opening69Reopen=function(){if(state.role!=='owner'||op().status!=='approved'||!validForm('op69ReopenForm'))return;const err=reopenBlock();if(err)return error(err);const reason=cleanText(value('op69ReopenReason'));if(!reason)return error('ပြန်ပြင်လိုသည့် အကြောင်းပြချက် ဖြည့်ပါ။');const o=op(),r=o.posted;state.lots=state.lots.filter(l=>!r.lots.some(x=>x.id===l.id));state.receipts=state.receipts.filter(x=>!r.receipts.some(y=>y.id===x.id));state.partnerAdvances=state.partnerAdvances.filter(a=>!r.advances.includes(a.id));state.supplierLoans38=(state.supplierLoans38||[]).filter(l=>!r.loans.includes(l.id));for(const add of r.stockAdds){const x=state.stockOpening.find(x=>x.key===add.key);if(x){x.qty-=add.qty;x.bags-=add.bags;}}for(const [id,n] of Object.entries(r.bases)){state.bases[id]=n;const a=state.masters.accounts.find(a=>a.id===id);if(a){a.openingBalance=r.accountMetadata[id].openingBalance;a.openingDate=r.accountMetadata[id].openingDate;if(r.accountMetadata[id].pendingOpening69)a.pendingOpening69=true;else delete a.pendingOpening69;}}state.day=r.previousDay;state.opening=r.previousOpening;o.status='draft';o.balances=[];o.dispatches=[];delete o.posted;o.revisions.push({at:new Date().toLocaleString('en-GB',{timeZone:'Asia/Rangoon'}),action:'မူကြမ်းပြန်ဖွင့်ခဲ့သည်',reason});save();workDirty=false;closeModal();ui.view='review';beginSetup('opening69');toast('အကြောင်းပြချက် မှတ်တမ်းတင်ပြီး မူကြမ်း ပြန်ဖွင့်ထားပါပြီ။');};
