ACCOUNT_NAMES.opening_credit69='စတင်ကြိုပေးငွေမှ နုတ်သုံး';
payableTotal=function(){return base69.payableTotal()+opening69Balance('payable');};
receivableTotal=function(){return base69.receivableTotal()+opening69Balance('receivable');};
loanBalance38=function(l,date=today()){const b=base69.loanBalance38(l,date);if(!l.opening69||date<l.date)return b;const extra=Number(l.openingInterest69)||0;return {...b,interest:Math.max(0,Math.round((b.accrued+extra-b.paidInterest)*100)/100),accrued:b.accrued+extra,openingInterest69:extra};};
statementData4=function(pArg,fromArg,toArg){const d=base69.statementData4(pArg,fromArg,toArg);if(!d||state.initialOpening69?.status!=='approved')return d;const extra=[];for(const b of op().balances.filter(b=>b.partnerId===d.p.id)){const key=b.type==='payable'?'payable':b.type==='receivable'?'receivable':'deposit';extra.push({date:b.date,ref:b.id,type:'စတင်လက်ကျန် · '+moneyNames[b.type],[key]:b.amount});for(const x of b.payments)extra.push({date:x.date,ref:b.id,type:x.mode==='opening_credit69'?'ကြိုပေးငွေ နုတ်သုံး':'စတင်လက်ကျန် ငွေရှင်း',[key]:-x.amount});}const o=extra.filter(x=>x.date<d.from),s=extra.filter(x=>x.date>=d.from&&x.date<=d.to);return {...d,opening:[...d.opening,...o].sort((a,b)=>a.date.localeCompare(b.date)),selected:[...d.selected,...s].sort((a,b)=>a.date.localeCompare(b.date))};};
function statementPanel(){const id=value('stParty');if(!id)return '';const o=state.initialOpening69;if(o?.status!=='approved')return '';const b=o.balances.filter(b=>b.partnerId===id);const p=supplierBy(id);return `<div id="op69StatementPanel">${b.length?`<section class="card mt"><h3 class="mb">${esc(p?.name||'')} · စတင်လက်ကျန်မှ ယနေ့ကျန်ငွေ</h3>${b.map(balanceCard).join('')}${b.flatMap(b=>b.payments.map(x=>`<p class="small muted">${shortDate(x.date)} · ${x.mode==='opening_credit69'?'အရောင်းတွင် နုတ်သုံး':x.mode==='cash'?'ငွေရှင်း':'မှတ်တမ်း'} · ${cashText(x.amount)}</p>`)).join('')}</section>`:''}${dispatchPanel(id)}</div>`;}
