setupView=function(){if(setupSection==='opening69')return page69();let html=base69.setupView();if(setupSection==='overview'){const t=document.createElement('div');t.innerHTML=html;const grid=t.querySelector('.v3-master-grid');if(grid)grid.insertAdjacentHTML('afterbegin',`<button class="v2-records-card v3-master-card op69-entry" onclick="openInitial69()"><span class="icon-box">${I('sun')}</span><strong>စတင်လက်ကျန် ထည့်မယ်</strong><p>ပွဲရုံပိုင်၊ ကုန်သည်၊ ဝယ်သူ · ကုန်နဲ့ငွေ</p><div class="v3-card-bottom"><span>${state.initialOpening69?.status==='approved'?'အတည်ပြုပြီး':'အဆင့်လိုက် ဖြည့်မယ်'}</span><span class="end-link">ဖွင့်မယ် ${I('arrow')}</span></div></button>`);html=t.innerHTML;}return html;};
